mapper.select:
SELECT * FROM ( SELECT R.REPORT_NO AS "reportNo", R.TARGET_TYPE AS "targetType", R.TARGET_NO AS "targetNo", R.REPORT_TYPE AS "reportType", R.DETAIL_REASON AS "detailReason", R.STATUS AS "status", R.RESULT AS "result", TO_CHAR(R.CREATED_AT, 'YYYY-MM-DD HH24:MI') AS "createdAt", TO_CHAR(R.UPDATED_AT, 'YYYY-MM-DD HH24:MI') AS "updatedAt", M.NICKNAME AS "reporterNickname", CASE R.TARGET_TYPE WHEN 'FREEBOARD' THEN (SELECT B.BOARD_TITLE FROM BOARD B WHERE B.BOARD_NO = R.TARGET_NO) WHEN 'COMPANION' THEN (SELECT CB.TITLE FROM COMPANION_BOARD CB WHERE CB.COMPANION_NO = R.TARGET_NO) WHEN 'REVIEW' THEN (SELECT CR.TITLE FROM COMPANION_REVIEW CR WHERE CR.REVIEW_NO = R.TARGET_NO) END AS "targetTitle", ROW_NUMBER() OVER (ORDER BY R.CREATED_AT DESC) AS RN FROM CONTENT_REPORT R JOIN MEMBER M ON R.MEMBER_NO = M.MEMBER_NO WHERE 1=1
AND R.STATUS = #{status}
AND R.TARGET_TYPE = #{targetType}
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

SELECT COUNT(*)
FROM CONTENT_REPORT R
WHERE 1=1

    AND R.STATUS = #{status}


    AND R.TARGET_TYPE = #{targetType}
